begin;
do $$ begin if current_user<>'postgres' then raise exception 'Offline postgres identity required';end if;end $$;
-- Developer webhooks (module 21, docs/ORYQEN_DEVELOPER_API.md). A signed-in person registers up to three https endpoints of their own;
-- ORYQEN posts signed events to them (today: credential.revoked when the holder revokes a credential, and a manual ping).
-- The signing secret is generated by the application, shown once, and kept here so the application can sign deliveries
-- on the owner's behalf. Rows are owner-only (forced RLS); only the owner's own session can read the secret.
create table private.developer_webhooks (
 id uuid primary key,
 owner_id uuid not null references private.profiles(id),
 url text not null check(char_length(url) between 12 and 300 and url ~ '^https://[^\s/?#@]+(/[^\s]*)?$'),
 secret text not null check(secret ~ '^[A-Za-z0-9_-]{43}$'),
 created_at timestamptz not null default transaction_timestamp()
);
create index developer_webhooks_owner_idx on private.developer_webhooks(owner_id,created_at);
create table private.developer_webhook_deliveries (
 id uuid primary key default gen_random_uuid(),
 webhook_id uuid not null references private.developer_webhooks(id) on delete cascade,
 owner_id uuid not null references private.profiles(id),
 event_id uuid not null,
 event_type text not null check(event_type in ('ping','credential.revoked')),
 attempt integer not null check(attempt between 1 and 5),
 outcome text not null check(outcome in ('delivered','failed')),
 status_code integer check(status_code is null or status_code between 100 and 599),
 at timestamptz not null default transaction_timestamp()
);
create index developer_webhook_deliveries_idx on private.developer_webhook_deliveries(webhook_id,at desc);
alter table private.developer_webhooks owner to fw_schema_owner;
alter table private.developer_webhook_deliveries owner to fw_schema_owner;
alter table private.developer_webhooks enable row level security;alter table private.developer_webhooks force row level security;
alter table private.developer_webhook_deliveries enable row level security;alter table private.developer_webhook_deliveries force row level security;
revoke all on private.developer_webhooks,private.developer_webhook_deliveries from public,anon,authenticated,service_role;
grant select,insert,delete on private.developer_webhooks to fw_user_exec;
grant select,insert,delete on private.developer_webhook_deliveries to fw_user_exec;
create policy developer_webhooks_owner_read on private.developer_webhooks for select to fw_user_exec using(private.is_active() and owner_id=private.request_uid());
create policy developer_webhooks_owner_insert on private.developer_webhooks for insert to fw_user_exec with check(private.is_active() and owner_id=private.request_uid() and created_at=transaction_timestamp());
create policy developer_webhooks_owner_delete on private.developer_webhooks for delete to fw_user_exec using(private.is_active() and owner_id=private.request_uid());
create policy developer_webhook_deliveries_owner_read on private.developer_webhook_deliveries for select to fw_user_exec using(private.is_active() and owner_id=private.request_uid());
create policy developer_webhook_deliveries_owner_insert on private.developer_webhook_deliveries for insert to fw_user_exec with check(private.is_active() and owner_id=private.request_uid() and at=transaction_timestamp());
create policy developer_webhook_deliveries_owner_delete on private.developer_webhook_deliveries for delete to fw_user_exec using(private.is_active() and owner_id=private.request_uid());

create function api.webhook_create(request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid; keys text[]:=array['webhookId','url','secret']; total integer; hook uuid;
begin
 actor:=private.require_identity();if not private.is_active() then raise exception 'AUTH_REQUIRED';end if;
 if request is null or jsonb_typeof(request)<>'object' or not(request ?& keys) or request-keys<>'{}'
  or (select count(*) from jsonb_each(request) e where jsonb_typeof(e.value)<>'string')>0
  or request->>'secret' !~ '^[A-Za-z0-9_-]{43}$' or request->>'url' !~ '^https://[^\s/?#@]+(/[^\s]*)?$' or char_length(request->>'url') not between 12 and 300 then raise exception 'VALIDATION_FAILED';end if;
 hook:=(request->>'webhookId')::uuid;
 perform private.consume_identity_quota('identity_write');perform pg_advisory_xact_lock(hashtextextended(actor::text,2716));
 select count(*) into total from private.developer_webhooks where owner_id=actor;
 if total>=3 then raise exception 'RATE_LIMITED';end if;
 insert into private.developer_webhooks(id,owner_id,url,secret) values(hook,actor,request->>'url',request->>'secret');
 return jsonb_build_object('webhookId',hook,'url',request->>'url');
exception when invalid_text_representation then raise exception 'VALIDATION_FAILED'; when unique_violation then raise exception 'IDEMPOTENCY_CONFLICT';end $$;

create function api.webhook_list(request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid; items jsonb;
begin
 actor:=private.require_identity();if not private.is_active() then raise exception 'AUTH_REQUIRED';end if;
 if request is null or jsonb_typeof(request)<>'object' or request<>'{}' then raise exception 'VALIDATION_FAILED';end if;
 perform private.consume_identity_quota('identity_read');
 select coalesce(jsonb_agg(jsonb_build_object('webhookId',w.id,'url',w.url,'createdAt',w.created_at,
   'lastDelivery',(select jsonb_build_object('at',d.at,'outcome',d.outcome,'statusCode',d.status_code,'eventType',d.event_type,'attempt',d.attempt) from private.developer_webhook_deliveries d where d.webhook_id=w.id order by d.at desc,d.id desc limit 1)) order by w.created_at,w.id),'[]') into items
  from private.developer_webhooks w where w.owner_id=actor;
 return jsonb_build_object('items',items);
end $$;

-- Server-side use only: returns the caller's own endpoints with their signing secrets so the application can sign a delivery.
create function api.webhook_targets(request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid; items jsonb;
begin
 actor:=private.require_identity();if not private.is_active() then raise exception 'AUTH_REQUIRED';end if;
 if request is null or jsonb_typeof(request)<>'object' or request<>'{}' then raise exception 'VALIDATION_FAILED';end if;
 perform private.consume_identity_quota('identity_read');
 select coalesce(jsonb_agg(jsonb_build_object('webhookId',w.id,'url',w.url,'secret',w.secret) order by w.created_at,w.id),'[]') into items from private.developer_webhooks w where w.owner_id=actor;
 return jsonb_build_object('items',items);
end $$;

create function api.webhook_delete(request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid; target uuid; removed integer;
begin
 actor:=private.require_identity();if not private.is_active() then raise exception 'AUTH_REQUIRED';end if;
 if request is null or jsonb_typeof(request)<>'object' or not(request ? 'webhookId') or request-array['webhookId']<>'{}' or jsonb_typeof(request->'webhookId') is distinct from 'string' then raise exception 'VALIDATION_FAILED';end if;
 target:=(request->>'webhookId')::uuid;
 perform private.consume_identity_quota('identity_write');
 delete from private.developer_webhooks where id=target and owner_id=actor;
 get diagnostics removed=row_count;
 if removed=0 then raise exception 'NOT_FOUND';end if;
 return jsonb_build_object('webhookId',target,'status','deleted');
exception when invalid_text_representation then raise exception 'VALIDATION_FAILED';end $$;

create function api.webhook_log(request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid; keys text[]:=array['webhookId','eventId','eventType','attempt','outcome','statusCode'];
begin
 actor:=private.require_identity();if not private.is_active() then raise exception 'AUTH_REQUIRED';end if;
 if request is null or jsonb_typeof(request)<>'object' or not(request ?& keys) or request-keys<>'{}'
  or request->>'eventType' not in ('ping','credential.revoked') or request->>'outcome' not in ('delivered','failed')
  or jsonb_typeof(request->'attempt') is distinct from 'number' or request->>'attempt' !~ '^[1-5]$'
  or (jsonb_typeof(request->'statusCode') is distinct from 'null' and (jsonb_typeof(request->'statusCode') is distinct from 'number' or request->>'statusCode' !~ '^[1-5][0-9]{2}$')) then raise exception 'VALIDATION_FAILED';end if;
 perform private.consume_identity_quota('identity_write');
 if not exists(select 1 from private.developer_webhooks w where w.id=(request->>'webhookId')::uuid and w.owner_id=actor) then raise exception 'NOT_FOUND';end if;
 insert into private.developer_webhook_deliveries(webhook_id,owner_id,event_id,event_type,attempt,outcome,status_code)
  values((request->>'webhookId')::uuid,actor,(request->>'eventId')::uuid,request->>'eventType',(request->>'attempt')::integer,request->>'outcome',case when jsonb_typeof(request->'statusCode')='null' then null else (request->>'statusCode')::integer end);
 return jsonb_build_object('logged',true);
exception when invalid_text_representation then raise exception 'VALIDATION_FAILED';end $$;

grant create on schema api to fw_user_exec;
alter function api.webhook_create(jsonb) owner to fw_user_exec;
alter function api.webhook_list(jsonb) owner to fw_user_exec;
alter function api.webhook_targets(jsonb) owner to fw_user_exec;
alter function api.webhook_delete(jsonb) owner to fw_user_exec;
alter function api.webhook_log(jsonb) owner to fw_user_exec;
revoke create on schema api from fw_user_exec;
revoke all on function api.webhook_create(jsonb),api.webhook_list(jsonb),api.webhook_targets(jsonb),api.webhook_delete(jsonb),api.webhook_log(jsonb) from public,anon,authenticated,service_role;
grant execute on function api.webhook_create(jsonb),api.webhook_list(jsonb),api.webhook_targets(jsonb),api.webhook_delete(jsonb),api.webhook_log(jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
